  {
    id: "1",
    date: "2026-03-15",
    routeName: "Morning Hill Climb",
    distance: 42.3,
    duration: "1:45:22",
    elevation: 820,
  },
  {
    id: "2",
    date: "2026-03-12",
    routeName: "Riverside Loop",
    distance: 28.7,
    duration: "1:10:45",
    elevation: 215,
  },
  {
    id: "3",
    date: "2026-03-10",
    routeName: "Mountain Pass Challenge",
    distance: 65.1,
    duration: "3:02:18",
    elevation: 1450,
  },
  {
    id: "4",
    date: "2026-03-07",
    routeName: "City Park Cruise",
    distance: 18.5,
    duration: "0:44:30",
    elevation: 85,
  },
  {
    id: "5",
    date: "2026-03-03",
    routeName: "Coastal Road Sprint",
    distance: 50.2,
    duration: "2:05:10",
    elevation: 340,
  },
];

export const monthlySummary = {
  totalDistance: 204.8, // km
  totalElevation: 2910, // meters
  avgSpeed: 24.6, // km/h
};

import StatCard from "@/components/StatCard";
import DashboardClient from "@/components/DashboardClient";
import { mockActivities, monthlySummary } from "@/lib/mockData";

export default function DashboardPage() {
  return (
    <div className="space-y-8 max-w-5xl">
      <div>
        <h1 className="text-2xl font-bold text-white">Dashboard</h1>
        <p className="text-sm text-gray-400 mt-1">Your cycling stats for this month</p>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard
          title="Monthly Distance"
          value={monthlySummary.totalDistance}
          unit="km"
          icon="🛣️"
        />
        <StatCard
          title="Total Elevation"
          value={monthlySummary.totalElevation.toLocaleString()}
          unit="m"
          icon="⛰️"
        />
        <StatCard
          title="Avg Speed"
          value={monthlySummary.avgSpeed}
          unit="km/h"
          icon="⚡"
        />
      </div>

      {/* Client section: activities table + upload */}
      <DashboardClient initialActivities={mockActivities} />
    </div>
  );
}

import Link from "next/link";

const navItems = [
  { label: "Dashboard", href: "/", icon: "📊" },
  { label: "Activities", href: "/activities", icon: "🚴" },
  { label: "Routes", href: "/routes", icon: "🗺️" },
  { label: "Stats", href: "/stats", icon: "📈" },
];

export default function Sidebar() {
  return (
    <aside className="w-56 bg-gray-900 border-r border-gray-800 flex flex-col shrink-0">
      <div className="px-6 py-5 border-b border-gray-800">
        <h1 className="text-lg font-bold tracking-tight text-white">
          🚴 CycleDash
        </h1>
        <p className="text-xs text-gray-400 mt-0.5">Personal Cycling Data</p>
      </div>
      <nav className="flex-1 px-3 py-4 space-y-1">
        {navItems.map((item) => (
          <Link
            key={item.href}
            href={item.href}
            className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-gray-300 hover:bg-gray-800 hover:text-white transition-colors"
          >
            <span>{item.icon}</span>
            <span>{item.label}</span>
          </Link>
        ))}
      </nav>
      <div className="px-6 py-4 border-t border-gray-800 text-xs text-gray-500">
        v0.1.0
      </div>
    </aside>
  );
}

